<?php

namespace MongoDB\Driver;

use MongoDB\BSON\Serializable;
use stdClass;

/**
 * <div id="class.mongodb-driver-serverapi" class="reference"> <h1 class="title">The MongoDB\Driver\ServerApi class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.10.0)</p>  <div class="section" id="mongodb-driver-serverapi.intro">   <h2 class="title">简介</h2>   <p class="simpara">   </p>  </div>  <div class="section" id="mongodb-driver-serverapi.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\ServerApi</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-serializable.php" class="interfacename">MongoDB\BSON\Serializable</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname">{@link MongoDB\Driver\ServerAPI::V1}</var><span class="initializer"> = "1"</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-serverapi.bsonserialize.php" class="methodname" style="color:#CC7832">bsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-serverapi.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$version</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span> <span class="parameter" style="color:#3A95FF">\$strict</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span> <span class="parameter" style="color:#3A95FF">\$deprecationErrors</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div>   }</div>  </div>  <div class="section" id="mongodb-driver-serverapi.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="mongodb-driver-serverapi.constants.v1"><strong><span>{@link MongoDB\Driver\ServerApi::V1}</span></strong></dt>     <dd>      <span class="simpara">Server API version 1.</span>     </dd>       </dl>  </div>  <div class="section" id="mongodb-driver-serverapi.examples">   <h2 class="title">示例</h2>   <div class="example" id="example-1">    <p><strong>示例 #1 Declare an API version on a manager</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">use </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">;<br>use </span><span style="color: #9876AA">MongoDB\Driver\ServerApi</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$v1 </span><span style="color: #007700">= new </span><span style="color: #9876AA">ServerApi</span><span style="color: #007700">(</span><span style="color: #9876AA">ServerApi</span><span style="color: #007700">::</span><span style="color: #9876AA">v1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017'</span><span style="color: #007700">, [], [</span><span style="color: #DD0000">'serverApi' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$v1</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$command </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Command</span><span style="color: #007700">([</span><span style="color: #DD0000">'buildInfo' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br><br>try {<br>    </span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeCommand</span><span style="color: #007700">(</span><span style="color: #DD0000">'admin'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$command</span><span style="color: #007700">);<br>} catch(</span><span style="color: #9876AA">MongoDB\Driver\Exception \$e</span><span style="color: #007700">) {<br>    echo </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br>    exit;<br>}<br><br></span><span style="color: #FF8000">// The buildInfo command returns a single result document, so we need to access<br> * the first result in the cursor. <br></span><span style="color: #9876AA">\$buildInfo </span><span style="color: #007700">= </span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">()[</span><span style="color: #9876AA">0</span><span style="color: #007700">];<br><br>echo </span><span style="color: #9876AA">\$buildInfo</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">version</span><span style="color: #007700">, </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="cdata"><blockquote style="border:1px gray solid;"><br>4.9.0-alpha7-49-gb968ca0<br></blockquote></div>    </div>   </div>   <div class="example" id="example-2">    <p><strong>示例 #2 Declare a strict API version on a manager</strong></p>    <div class="example-contents"><p>     The following example sets the <span class="parameter" style="color:#3A95FF">strict</span> flag, which     tells the server to reject any command that is not part of the declared API     version. This results in an error when running the buildInfo command.    </p></div>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">use </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">;<br>use </span><span style="color: #9876AA">MongoDB\Driver\ServerApi</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$v1 </span><span style="color: #007700">= new </span><span style="color: #9876AA">ServerApi</span><span style="color: #007700">(</span><span style="color: #9876AA">ServerApi</span><span style="color: #007700">::</span><span style="color: #9876AA">v1</span><span style="color: #007700">, </span><span style="color: #9876AA">true</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017'</span><span style="color: #007700">, [], [</span><span style="color: #DD0000">'serverApi' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$v1</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$command </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Command</span><span style="color: #007700">([</span><span style="color: #DD0000">'buildInfo' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br><br>try {<br>    </span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeCommand</span><span style="color: #007700">(</span><span style="color: #DD0000">'admin'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$command</span><span style="color: #007700">);<br>} catch(</span><span style="color: #9876AA">MongoDB\Driver\Exception \$e</span><span style="color: #007700">) {<br>    echo </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br>    exit;<br>}<br><br></span><span style="color: #FF8000">// The buildInfo command returns a single result document, so we need to access<br> * the first result in the cursor. <br></span><span style="color: #9876AA">\$buildInfo </span><span style="color: #007700">= </span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">()[</span><span style="color: #9876AA">0</span><span style="color: #007700">];<br><br>echo </span><span style="color: #9876AA">\$buildInfo</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">version</span><span style="color: #007700">, </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="cdata"><blockquote style="border:1px gray solid;"><br>Provided&nbsp;apiStrict:true,&nbsp;but&nbsp;the&nbsp;command&nbsp;buildInfo&nbsp;is&nbsp;not&nbsp;in&nbsp;API&nbsp;Version&nbsp;1<br></blockquote></div>    </div>   </div>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\ServerApi::bsonSerialize} — Returns an object for BSON serialization</li><li>{@link MongoDB\Driver\ServerApi::__construct} — Create a new ServerApi instance</li></ul></div>
 */
final class ServerApi implements Serializable
{
    public const V1 = 1;

/**
 * <div id="mongodb-driver-serverapi.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ServerApi::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.10.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ServerApi::__construct</span> — <span class="dc-title">Create a new ServerApi instance</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-serverapi.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ServerApi::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$version</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span> <span class="parameter" style="color:#3A95FF">\$strict</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span> <span class="parameter" style="color:#3A95FF">\$deprecationErrors</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div>  <p class="simpara">   Creates a new <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverapi.php" class="classname">MongoDB\Driver\ServerApi</a></span> instance used to   declare an API version when creating a   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-manager.php" class="classname">MongoDB\Driver\Manager</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-serverapi.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt id="mongodb-driver-serverapi.construct-version"><span class="parameter" style="color:#3A95FF">version</span></dt>    <dd>     <span class="simpara">      A server API version.     </span>     <span class="simpara">      Supported API versions are provided as constants in      <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverapi.php" class="classname">MongoDB\Driver\ServerApi</a></span>. The only supported API      version is <strong><span>{@link MongoDB\Driver\ServerApi::V1}</span></strong>.     </span>    </dd>          <dt id="mongodb-driver-manager.construct-strict"><span class="parameter" style="color:#3A95FF">strict</span></dt>    <dd>     <span class="simpara">      If the <span class="parameter" style="color:#3A95FF">strict</span> parameter is set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, the      server will yield an error for any command that is not part of the      specified API version. If no value is provided, the server default value      (<strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>) is used.     </span>    </dd>          <dt id="mongodb-driver-manager.construct-deprecationErrors"><span class="parameter" style="color:#3A95FF">deprecationErrors</span></dt>    <dd>     <span class="simpara">      If the <span class="parameter" style="color:#3A95FF">deprecationErrors</span> parameter is set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>,      the server will yield an error when using a command that is deprecated in      the specified API version. If no value is provided, the server default value      (<strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>) is used.     </span>    </dd>     </dl> </div></div>
 */
    final public function __construct(string $version, ?bool $strict = false, ?bool $deprecationErrors = false) {}


    public static function __set_state(array $properties) {}

/**
 * <div id="mongodb-driver-serverapi.bsonserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ServerApi::bsonSerialize</h1>  <p class="verinfo">(mongodb &gt;=1.10.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ServerApi::bsonSerialize</span> — <span class="dc-title">Returns an object for BSON serialization</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-serverapi.bsonserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ServerApi::bsonSerialize</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-serverapi.bsonserialize-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-serverapi.bsonserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an object for serializing the ServerApi as BSON.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-serverapi.bsonserialize-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-serverapi.bsonserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Serializable::bsonSerialize()} - Provides an array or document to serialize as BSON</span></li>  </ul> </div></div>
 */
    final public function bsonSerialize(): stdClass {}
}
